import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"TraeCode 教程","description":"从官方下载中心安装 TraeCode，完成首次设置，打开第一个项目，并在 IDE 模式与 SOLO 模式之间切换。中国站与国际站是两套表面，不要混装。","frontmatter":{"title":"TraeCode 教程","description":"从官方下载中心安装 TraeCode，完成首次设置，打开第一个项目，并在 IDE 模式与 SOLO 模式之间切换。中国站与国际站是两套表面，不要混装。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/trae/trae.md","filePath":"zh/products/trae/trae.md","lastUpdated":1787107158000}'),n={name:"zh/products/trae/trae.md"};function l(i,t,s,d,h,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="traecode-教程" tabindex="-1">TraeCode 教程 <a class="header-anchor" href="#traecode-教程" aria-label="Permalink to &quot;TraeCode 教程&quot;">​</a></h1><blockquote><p>本页带你把 <strong>TraeCode</strong> 装上并打开第一个项目。安装路径抄自国际站 <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a> 和中国站 <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">快速开始</a>。家族边界见 <a href="./">学习地图</a>。OS / 设备上限 / 官方 URL 见 <a href="./trae-cheatsheet.html">速查表</a>。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>目标</strong></p><ul><li>分清中国站（<code>trae.cn</code> / <code>trae.com.cn</code>）和国际站（<code>trae.ai</code>）</li><li>从官方下载页装上 TraeCode 桌面 IDE</li><li>打开本地文件夹，或按官方步骤克隆仓库</li><li>在左上角切换 <strong>IDE 模式</strong> 与 <strong>SOLO 模式</strong></li></ul><p><strong>非目标</strong></p><ul><li>不写 TraeWork / 豆包 / 扣子 / 方舟教程</li><li>不编 <code>brew</code> / <code>npm</code> / curl 安装命令（官方安装是下载安装包）</li><li>不编 TraeCode CLI（企业页写 <strong>coming soon</strong>）</li><li>不把 Legacy 套餐次数表抄成现行价格</li></ul><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><p>国际站 <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a> 与中国站 <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">快速开始</a> 列出的操作系统：</p><table tabindex="0"><thead><tr><th>操作系统</th><th>架构</th><th>官方写明的版本 / 格式</th></tr></thead><tbody><tr><td>macOS</td><td>Apple Silicon、Intel</td><td><strong>12.0</strong> 或更高</td></tr><tr><td>Windows</td><td>64 位（x64）</td><td><strong>Windows 10、Windows 11</strong></td></tr><tr><td>Linux</td><td>64 位（x64）、64 位（ARM64）</td><td><code>.deb</code>：Ubuntu 20.04、Debian 11；<code>.rpm</code>：Fedora 42、RHEL 9.x</td></tr></tbody></table><p>账号：一个 TRAE 账号。登录方式随表面不同，见第 3 节。</p><h2 id="_1-选表面-中国站-vs-国际站" tabindex="-1">1. 选表面：中国站 vs 国际站 <a class="header-anchor" href="#_1-选表面-中国站-vs-国际站" aria-label="Permalink to &quot;1. 选表面：中国站 vs 国际站&quot;">​</a></h2><p>官方国际站顶栏有「前往中国站」。两套不是镜像。</p><table tabindex="0"><thead><tr><th></th><th>国际站</th><th>中国站</th></tr></thead><tbody><tr><td>营销 / 下载</td><td><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a> · <a href="https://www.trae.ai/download" target="_blank" rel="noreferrer">www.trae.ai/download</a></td><td><a href="https://www.trae.cn/" target="_blank" rel="noreferrer">www.trae.cn</a> · 快速开始链 <a href="https://www.trae.com.cn" target="_blank" rel="noreferrer">www.trae.com.cn</a></td></tr><tr><td>文档</td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai</a></td><td><a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">docs.trae.cn</a>（有 <a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer"><code>llms.txt</code></a>）</td></tr><tr><td>设备上限</td><td><strong>3</strong> 台（<a href="https://docs.trae.ai/ide/device-limit" target="_blank" rel="noreferrer">device-limit</a>）</td><td><strong>10</strong> 台（<a href="https://docs.trae.cn/ide_device-limit.md" target="_blank" rel="noreferrer">ide_device-limit.md</a>）</td></tr><tr><td>登录（官方已写明）</td><td></td><td>手机号、抖音账号、苹果账号、稀土掘金账号（<a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">快速开始</a>）</td></tr></tbody></table><p>在同一台电脑上不要混用两套安装包当「同一个产品」。账号、额度、设备计数各自独立。</p><h2 id="_2-从官方下载安装" tabindex="-1">2. 从官方下载安装 <a class="header-anchor" href="#_2-从官方下载安装" aria-label="Permalink to &quot;2. 从官方下载安装&quot;">​</a></h2><p>官方<strong>没有</strong>给出 <code>curl | bash</code> 或 npm 全局包。安装入口是下载中心。</p><h3 id="国际站" tabindex="-1">国际站 <a class="header-anchor" href="#国际站" aria-label="Permalink to &quot;国际站&quot;">​</a></h3><ol><li>打开 <a href="https://www.trae.ai/download" target="_blank" rel="noreferrer">Download Center</a>。</li><li>找到 <strong>TraeCode</strong> 区块（原文：Your 10x AI Coding Engineer；<strong>Seamless switch between IDE and SOLO Mode</strong>）。不要下成同页的 <strong>TraeWork</strong>。</li><li>按本机选择 macOS（12.0+，含 Intel）、Windows 10/11，或 <code>.deb</code> / <code>.rpm</code>。</li><li>装完启动。</li></ol><p>国际站 Quickstart：前往官网，点右上角 <strong>下载 IDE</strong>，把安装包下到本地并安装。</p><p>macOS 低于 12：国际站中文 Quickstart 写过「下载低于 3.5.25 版本」。具体安装包链接以该页当时给出的 Apple Silicon / Intel 链为准，本页不另造 URL。</p><h3 id="中国站" tabindex="-1">中国站 <a class="header-anchor" href="#中国站" aria-label="Permalink to &quot;中国站&quot;">​</a></h3><p>中国站 <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">快速开始</a> 原文：</p><ol><li>前往 <a href="https://www.trae.com.cn" target="_blank" rel="noreferrer">TRAE 官网</a>，点击右上角的 <strong>下载 IDE</strong> 按钮，将安装包下载到本地并完成安装。</li><li>若 macOS 低于 12，直接下载<strong>低于 3.3.25</strong> 版本的 TRAE IDE： <ul><li><a href="https://lf-cdn.trae.com.cn/obj/trae-com-cn/pkg/app/releases/stable/2.3.4283/darwin/Trae%20CN-darwin-arm64.dmg" target="_blank" rel="noreferrer">Apple Silicon 芯片</a></li><li><a href="https://lf-cdn.trae.com.cn/obj/trae-com-cn/pkg/app/releases/stable/2.3.4283/darwin/Trae%20CN-darwin-x64.dmg" target="_blank" rel="noreferrer">Intel 芯片</a></li></ul></li></ol><p>不要把中国站的 <code>3.3.25</code> 和国际站摘要里的 <code>3.5.25</code> 合成一个数字。</p><h2 id="_3-首次设置与登录" tabindex="-1">3. 首次设置与登录 <a class="header-anchor" href="#_3-首次设置与登录" aria-label="Permalink to &quot;3. 首次设置与登录&quot;">​</a></h2><p>启动后跟随界面指引。中国站快速开始列出的步骤：</p><ul><li>选择主题和语言</li><li>从 <strong>VS Code 或 Cursor</strong> 导入已有配置</li><li>添加 TRAE 相关的命令行</li><li>登录（中国站账号类型见第 1 节）</li></ul><p>国际站 <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a> 同样把 IDE 能力写成完整编辑器 + Git + 扩展生态。首次设置的具体文案以你下载的那一站安装向导为准。</p><p>「添加 TRAE 相关的命令行」是官方向导里的一步。官方页<strong>没有</strong>写出可执行文件名或 <code>brew install</code> 字符串，本页不补。</p><p>中国站额外步骤（同一篇快速开始）：前往 <strong>设置 &gt; 开发环境</strong>，配置 Node.js。可以添加本机已装的 SDK，或下载 TRAE IDE 内置的 Node.js SDK。</p><h2 id="_4-打开第一个项目" tabindex="-1">4. 打开第一个项目 <a class="header-anchor" href="#_4-打开第一个项目" aria-label="Permalink to &quot;4. 打开第一个项目&quot;">​</a></h2><p>官方提供三种入口（国际站 Quickstart / 中国站快速开始原文一致）：</p><p><strong>导入本地文件夹</strong></p><ol><li>点左侧面板中央的 <strong>打开文件夹</strong>，或左上角 <strong>选择项目 &gt; 打开文件夹</strong>。</li><li>选一个本地文件夹打开。</li></ol><p><strong>从 GitHub 克隆</strong></p><ol><li>点 <strong>克隆 Git 仓库</strong>，或 <strong>选择项目 &gt; 克隆 Git 仓库</strong>。</li><li>在顶部面板点 <strong>从 GitHub 克隆</strong>。</li><li>完成 GitHub 授权，把仓库克隆到本地并打开。</li></ol><p><strong>从 URL 克隆</strong></p><ol><li>同样进入 <strong>克隆 Git 仓库</strong>。</li><li>输入仓库 URL，点 <strong>存储库 URL {URL}</strong>。</li><li>按提示克隆并打开。</li></ol><p>打开之后，先在 IDE 模式里看目录和终端是否正常。再让智能体只读摸底仓库结构。改文件前看清 diff，不要一上来开自动运行。</p><h2 id="_5-切换-ide-模式与-solo-模式" tabindex="-1">5. 切换 IDE 模式与 SOLO 模式 <a class="header-anchor" href="#_5-切换-ide-模式与-solo-模式" aria-label="Permalink to &quot;5. 切换 IDE 模式与 SOLO 模式&quot;">​</a></h2><p>官方：<a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a>、<a href="https://docs.trae.ai/ide/solo-mode" target="_blank" rel="noreferrer">SOLO 模式概览</a>、<a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">快速开始</a>。</p><p>在界面<strong>左上角</strong>用模式切换按钮切换。</p><table tabindex="0"><thead><tr><th>模式</th><th>官方行为</th><th>适合</th></tr></thead><tbody><tr><td><strong>IDE 模式</strong></td><td>保留编辑器、终端、调试、插件、源代码管理；你控制每一步</td><td>精细改已有仓库</td></tr><tr><td><strong>SOLO 模式</strong></td><td>AI 主导，自动规划并走完需求理解、代码生成、测试、成果预览（SOLO 页还写到部署）</td><td>从自然语言推一条垂直功能</td></tr></tbody></table><p>SOLO 怎么开：把模式切到 <strong>SOLO</strong>。界面从左到右是任务管理面板、AI 对话面板、工具面板（<a href="https://docs.trae.ai/ide/solo-mode" target="_blank" rel="noreferrer">SOLO 模式概览</a>）。</p><p>输入方式（SOLO 页原文）：自然语言、语音、上传本地文件。</p><p>SOLO 页还列出：SOLO Agent、多任务、工具面板（编辑器 / 文档 / 浏览器）、Figma 导入、Supabase、部署（举例 Vercel）、AI 服务、支付（举例 Stripe）、变更 diff。逐步操作跟对应官方子页，本教程不展开成第二份 How-to。</p><p><strong>不要</strong>为了「SOLO」去装 TraeWork。TraeWork 是独立客户端，官方写它建立在 TraeCode SOLO 模式之上。</p><h2 id="_6-智能体与-cue" tabindex="-1">6. 智能体与 CUE <a class="header-anchor" href="#_6-智能体与-cue" aria-label="Permalink to &quot;6. 智能体与 CUE&quot;">​</a></h2><p><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a> / <a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">中国站同页</a>：</p><ul><li><strong>智能体</strong>：自然语言定义任务；检索代码库、多步计划、调工具。可自建智能体，并配提示词、MCP Server、工具集。</li><li><strong>CUE</strong>：代码补全、链式补全、多行修改、修改点预测与跳转；在 <strong>Python、TypeScript、Golang</strong> 项目里辅助导入依赖和重命名引用。</li><li><strong>上下文</strong>：文件、文件夹、代码片段、终端输出、仓库、文档集、网页。</li><li><strong>模型</strong>：内置多模型，也可用 API Key 加自定义模型（名单以 <a href="https://docs.trae.ai/ide/models" target="_blank" rel="noreferrer">models</a> 当天表格为准，本页不抄易过期名单）。</li></ul><p>中国站 What is TraeCode 另有「速通」权益：模型排队时加速当次 Query。规则去中国站该节，国际站英文 What is TraeCode 2026-08-19 <strong>没有</strong>同一段。</p><p>安全（两站 What is 页一致）：</p><ul><li><strong>隐私模式</strong>：开启后，对话、代码片段、AI 输出不用于数据分析、产品优化或模型训练。代码库文件留在本地设备。</li><li><strong>沙箱</strong>：智能体命令可在受限环境执行，带文件访问控制和高风险命令拦截。</li></ul><h2 id="_7-设备数量" tabindex="-1">7. 设备数量 <a class="header-anchor" href="#_7-设备数量" aria-label="Permalink to &quot;7. 设备数量&quot;">​</a></h2><p>计入设备的客户端（两站原文结构相同）：<strong>TraeCode</strong>、<strong>TraeWork 桌面版</strong>、<strong>TRAE 移动端</strong>。<strong>TraeWork 网页版不计入</strong>。同一台电脑同时登 TraeCode 和 TraeWork 桌面版，计 <strong>1</strong> 台。</p><p>上限数字不同：</p><ul><li>国际站：<strong>3</strong> 台（<a href="https://docs.trae.ai/ide/device-limit" target="_blank" rel="noreferrer">device-limit</a>）</li><li>中国站：<strong>10</strong> 台（<a href="https://docs.trae.cn/ide_device-limit.md" target="_blank" rel="noreferrer">ide_device-limit.md</a>）</li></ul><p>达到上限后，登录页会进入 Device limit reached / <strong>设备数量已达上限</strong>。先在已登录设备上 <strong>Sign out</strong> / <strong>退出登录</strong>。若该设备同时开着 TraeCode 和 TraeWork 桌面版，登出一次会一并退出。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ol><li><strong>下载页点成 TraeWork。</strong> TraeCode 才是本教程的 IDE。</li><li><strong>中国站包和国际站包混用、账号混登。</strong> 设备上限和登录方式都不同。</li><li><strong>把 SOLO 模式当成要另装的 TraeWork。</strong> SOLO 是 TraeCode 左上角的模式。</li><li><strong>编了一个 CLI 安装命令。</strong> 官方当前是下载安装包；CLI 在企业页是 coming soon。</li><li><strong>把 Legacy 套餐次数表当成现行价格。</strong> 跟 <a href="https://www.trae.ai/pricing" target="_blank" rel="noreferrer">pricing</a> 和现行「套餐与计费」页。</li><li><strong>旧 macOS 回退链抄错站。</strong> 中国站官方直链版本是低于 <strong>3.3.25</strong> 的 Trae CN dmg；不要套到国际站。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>官方 URL、OS、设备上限 → <a href="./trae-cheatsheet.html">速查表</a></li><li>家族边界 → <a href="./">学习地图</a></li><li>Skills / MCP / 自定义智能体 → 官方 <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai</a> 或 <a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer">docs.trae.cn/llms.txt</a></li></ul>',63)])])}const u=r(n,[["render",l]]);export{m as __pageData,u as default};
